def binary_search(
    values: list[int],
    target: int,
    low: int = 0,
    high: int | None = None,
) -> int:
    if high is None:
        high = len(values) - 1
    if low > high:
        return -1
    middle = (low + high) // 2
    if values[middle] == target:
        return middle
    if values[middle] < target:
        return binary_search(values, target, middle + 1, high)
    return binary_search(values, target, low, middle - 1)


