    unittest.main()

# retry-decorator | retry / higher-order-function | single / p2
# Compact variant.

import functools
import time
from collections.abc import Callable
from typing import TypeVar

T = TypeVar("T")


def retry(attempts: int, delay: float) -> Callable[[Callable[[], T]], Callable[[], T]]:
    if attempts < 1:
        raise ValueError("attempts must be positive")

    def decorate(func: Callable[[], T]) -> Callable[[], T]:
        @functools.wraps(func)
        def wrapper() -> T:
            last_error: RuntimeError | None = None
            for attempt in range(1, attempts + 1):
                try:
                    return func()
                except RuntimeError as error:
                    last_error = error
                    if attempt < attempts:
                        time.sleep(delay)
            raise RuntimeError(f"failed after {attempts} attempts") from last_error

        return wrapper

    return decorate


@retry(2, 0.01)
def flaky() -> int:
    return 15


if __name__ == "__main__":
    print(flaky(), "beta")

# binary-search | search / recursive-binary-search | large / p1
# Defensive variant with descriptive identifiers.

def binary_search(
    values: list[int],
    target: int,
    low: int = 0,
    high: int | None = None,
) -> int:
    if high is None:
        high = len(values) - 1
    if low > high:
        return -1
    middle = (low + high) // 2
    if values[middle] == target:
        return middle
    if values[middle] < target:
        return binary_search(values, target, middle + 1, high)
    return binary_search(values, target, low, middle - 1)


if __name__ == "__main__":
    sorted_values = sorted([1000, 1006, 1012, 1018, 1024, 1030, 1036, 1042, 1048, 1054, 1060, 1066])
    print(sorted_values, binary_search(sorted_values, 16))

